  {"prompt": "Συνώνυμο/ορισμός: που βρίσκονται δίπλα στη θάλασσα", "options": [], "answer": "παραθαλάσσια", "answer_note": "παραθαλάσσιος = seaside, coastal."},
  {"prompt": "Συνώνυμο/ορισμός: στενό υπόγειο πέρασμα", "options": [], "answer": "σήραγγα", "answer_note": "η σήραγγα = tunnel."},
